<?php namespace App\Models;
use App\Core\Database;
final class Car{
public static function search(array $f,int $limit=24):array{$w=["c.status='active'"];$p=[];if($f['q']??''){$w[]='(c.title LIKE ? OR c.brand LIKE ? OR c.model LIKE ? OR c.city LIKE ?)';$v='%'.$f['q'].'%';array_push($p,$v,$v,$v,$v);}foreach(['brand','transmission','fuel'] as $x)if($f[$x]??''){$w[]="c.$x=?";$p[]=$f[$x];}if($f['min']??''){$w[]='c.price>=?';$p[]=(int)$f['min'];}if($f['max']??''){$w[]='c.price<=?';$p[]=(int)$f['max'];}$sort=match($f['sort']??'newest'){'price_asc'=>'c.price ASC','price_desc'=>'c.price DESC','year'=>'c.year DESC',default=>'c.created_at DESC'};$sql='SELECT c.*,u.name seller,(SELECT path FROM car_images WHERE car_id=c.id ORDER BY is_primary DESC,id LIMIT 1) image FROM cars c JOIN users u ON u.id=c.user_id WHERE '.implode(' AND ',$w)." ORDER BY $sort LIMIT ".(int)$limit;$s=Database::connection()->prepare($sql);$s->execute($p);return$s->fetchAll();}
public static function find(int $id):?array{$s=Database::connection()->prepare('SELECT c.*,u.name seller,u.phone seller_phone FROM cars c JOIN users u ON u.id=c.user_id WHERE c.id=?');$s->execute([$id]);$car=$s->fetch();if(!$car)return null;$i=Database::connection()->prepare('SELECT * FROM car_images WHERE car_id=? ORDER BY is_primary DESC,id');$i->execute([$id]);$car['images']=$i->fetchAll();return$car;}
public static function byUser(int $uid):array{$s=Database::connection()->prepare('SELECT c.*,(SELECT path FROM car_images WHERE car_id=c.id ORDER BY is_primary DESC,id LIMIT 1) image FROM cars c WHERE user_id=? ORDER BY created_at DESC');$s->execute([$uid]);return$s->fetchAll();}
public static function create(array $d,array $images):int{$db=Database::connection();$db->beginTransaction();try{$s=$db->prepare('INSERT INTO cars(user_id,title,brand,model,year,price,mileage,transmission,fuel,color,city,description,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$s->execute([$d['user_id'],$d['title'],$d['brand'],$d['model'],$d['year'],$d['price'],$d['mileage'],$d['transmission'],$d['fuel'],$d['color'],$d['city'],$d['description'],'active']);$id=(int)$db->lastInsertId();$q=$db->prepare('INSERT INTO car_images(car_id,path,is_primary) VALUES(?,?,?)');foreach($images as $k=>$path)$q->execute([$id,$path,$k===0]);$db->commit();return$id;}catch(\Throwable $e){$db->rollBack();throw$e;}}
public static function update(int $id,int $uid,array $d):bool{$s=Database::connection()->prepare('UPDATE cars SET title=?,brand=?,model=?,year=?,price=?,mileage=?,transmission=?,fuel=?,color=?,city=?,description=?,status=?,updated_at=NOW() WHERE id=? AND user_id=?');return$s->execute([$d['title'],$d['brand'],$d['model'],$d['year'],$d['price'],$d['mileage'],$d['transmission'],$d['fuel'],$d['color'],$d['city'],$d['description'],$d['status'],$id,$uid]);}
public static function delete(int $id,int $uid):bool{$s=Database::connection()->prepare('DELETE FROM cars WHERE id=? AND user_id=?');return$s->execute([$id,$uid]);}
public static function toggleFavorite(int $car,int $user):bool{$db=Database::connection();$s=$db->prepare('SELECT id FROM favorites WHERE car_id=? AND user_id=?');$s->execute([$car,$user]);if($s->fetch()){$db->prepare('DELETE FROM favorites WHERE car_id=? AND user_id=?')->execute([$car,$user]);return false;}$db->prepare('INSERT INTO favorites(car_id,user_id,created_at) VALUES(?,?,NOW())')->execute([$car,$user]);return true;}
public static function isFavorite(int $car,int $user):bool{$s=Database::connection()->prepare('SELECT 1 FROM favorites WHERE car_id=? AND user_id=?');$s->execute([$car,$user]);return(bool)$s->fetchColumn();}}
